const { spawn } = require('child_process')

module.exports = run_command

// runs a command without a shell, resolves with its output
function run_command ({ command, args, env = process.env }) {
  return new Promise(start_process)
  function start_process (resolve, reject) {
    const child = spawn(command, args, { stdio: ['ignore', 'pipe', 'pipe'], env })
    const out = []
    const err = []
    child.stdout.on('data', data => out.push(data))
    child.stderr.on('data', data => err.push(data))
    child.on('error', reject)
    child.on('close', code => code === 0 ? resolve(Buffer.concat(out).toString()) : reject(new Error(`${command} ${args.join(' ')}: ${Buffer.concat(err).toString().trim()}`)))
  }
}
